CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),customer_name TEXT NOT NULL,address TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'placed' CHECK(status IN ('placed','packing','shipped','returned','cancelled')),total_cents INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),name TEXT NOT NULL,price_cents INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0));
